  Now, it is much easier to parametrize the roots $\zeta_1, \ldots, \zeta_4$, which will be useful in the sequel. Take again $h=0$, then the final result will be within $O(h)$. We have the equation
  $$
  z^4-z^2=-c=m^4-m^2.
  $$
  This has solutions $z_{1,2}=\pm m, z_{3,4}=\pm \sqrt{1-m^2}$. By the restriction, $m\in (0, \f{1}{\sqrt{2}})$, we have that $\sqrt{1-m^2}>m$, whence we arrive at the following formulas
  \begin{equation}
  \label{20}
  \zeta_1=-\sqrt{1-m^2}+O(h),\  \zeta_2=-m+O(h),\  \zeta_3=m,\  \zeta_4=\sqrt{1-m^2}+O(h).
  \end{equation}

Thus, we have located the former modulational invariance eigenvalue - namely it is $\mu_0 \sqrt{h}$,
where $\mu_0$ ensures $4  \varphi_0^2(a_0 \Psi_1^0+b_0 \Psi_2^0)  - \mu_0^2  L_+^{-1}[\varphi_0]\perp \varphi_0$.
Equivalently
\begin{equation}
\label{610}
\mu_0^2 = 4 \f{\dpr{\varphi_0^2(a_0 \Psi_1^0+b_0 \Psi_2^0)}{\varphi_0}}{\dpr{L_+^{-1}\varphi_0}{\varphi_0}}.
\end{equation}
It remains to compute this last expression. We have
\begin{eqnarray*}
\mu_0^2 &=& 4\f{\dpr{\varphi_0^3}{a_0 \Psi_1^0+b_0 \Psi_2^0}}{\dpr{L_+^{-1}\varphi_0}{\varphi_0}}=
4 \f{a_0}{ \dpr{L_+^{-1}\varphi_0}{\varphi_0}} \dpr{\varphi_0^3}{L_+^{-1}[1]}=  -a_0  \f{\dpr{\varphi_0}{1}}{\dpr{L_+^{-1}\varphi_0}{\varphi_0}}
\end{eqnarray*}
Since $\dpr{L_+^{-1}\varphi_0}{\varphi_0}<0$, we have that $sgn(\mu_0^2)=sgn(a_0)$. In other words, if $a_0>0$, we have instability, while for $a_0<0$, we have a marginally stable pairs of eigenvalues
$\pm i [\sqrt  \f{-a_0 \dpr{\varphi_0}{1}}{\dpr{L_+^{-1}\varphi_0}{\varphi_0}} \sqrt{h}+O(h)]$

$O(1)$ solutions of \eqref{151
- an informal analysis of the profile equation}

 As we have mentioned above, we shall use $h$ as a small parameter, by taking $\alpha:=\alpha_0 h, \alpha_0=O(1)$.  Next, we assume that \eqref{151} (or equivalently \eqref{160}) has a solution.  In addition, we model  $\tilde{\cl}$ to be a small perturbation of ${\mathcal L}_{-,0}$. In particular, it has a small (and simple) eigenvalue close to zero (in order to produce $O(1)$ solutions of \eqref{160}), denoted by $\sigma_h=\sigma_0 h+O(h^2)$, with a corresponding eigenfunction $\varphi_h=\varphi_0+O(h)$. In addition, the next eigenvalue is positive and order $O(1)$.

   By projecting \eqref{160}  onto $\varphi_h$ and its complementary subspace  $\{\varphi_h\}^\perp$, we arrive at the formula
 \begin{eqnarray}
 \label{165}
 \varphi_{\alpha,1} &=& \f{h \sigma}{\sigma^2+\alpha^2} \f{\dpr{1}{\varphi_h}}{\|\varphi_h\|^2} \varphi_h+q_1, \ \ q_1=O(h), q_1 \in \{\varphi_h\}^\perp \\
 \label{167}
  \varphi_{\alpha,2} &=& \f{\alpha h}{\sigma^2+\alpha^2} \f{\dpr{1}{\varphi_h}}{\|\varphi_h\|^2} \varphi_h+q_2, \ \ q_2=O(h^2), q_2 \in \{\varphi_h\}^\perp
 \end{eqnarray}
 One can in principle continue with the construction of $\varphi_{\alpha,1}, \varphi_{\alpha,2}$ based on \eqref{165} and
 \eqref{167}, but it becomes hard to keep track of the expansion of $\sigma_h$ in powers of $h$. Instead, we will pass to the known waves $\varphi_0$, since we have a good understanding  of the operator ${\mathcal L}_{-,0}$, which we denote by $L_{-}$ henceforth\footnote{Also, we introduce $L_+:={\mathcal L}_{+,0}$}. More precisely, we postulate the form
 \begin{eqnarray}
 \label{170}
 \varphi_{\alpha,1} &=& (a_0+a_1 h+O(h^2))\varphi_0+ h \Psi_1, \ \ \Psi_1\perp \varphi_0  \\
 \label{175}
  \varphi_{\alpha,2} &=& (b_0+b_1 h+O(h^2))\varphi_0+ h \Psi_2,  \ \ \Psi_2\perp \varphi_0
 \end{eqnarray}
 Comparing the expansions \eqref{165} with \eqref{170}(and \eqref{167} with \eqref{175} respectively), we have the formula
 \begin{eqnarray}
 \label{180}
  a_0 &=& \f{\sigma_0}{\sigma_0^2+\alpha_0^2} \f{\dpr{1}{\varphi_0}}{\|\varphi_0\|^2}  \\
 \label{185}
 b_0 &=& \f{\alpha_0}{\sigma_0^2+\alpha_0^2} \f{\dpr{1}{\varphi_0}}{\|\varphi_0\|^2}
\end{eqnarray}
 Next, using the form of the operator $\tilde{\cl}$, we have
 $$
 \tilde{\cl}=-\partial_x^2+1 - 2(\varphi_{\alpha,1}^2+\varphi_{\alpha,2}^2)= -\partial_x^2+1 - 2(a_0^2+b_0^2)\varphi_0^2+O(h).
 $$
 Since we require that $\tilde{\cl}$ be a perturbation of $L_-$, we must have $a_0^2+b_0^2=1$. This, together with \eqref{180} and \eqref{185} implies that $\sigma_0$ is completely determined by $\alpha_0$ and in fact,
 \begin{equation}
 \label{211}
 \sigma_0^2+\alpha_0^2=\f{\dpr{1}{\varphi_0}^2}{\|\varphi_0\|^4}.
 \end{equation}
 We can rewrite the equation \eqref{151} equivalently as follows
 \begin{equation}
 \label{190}
 (\tilde{\cl}-i\alpha)[i (\varphi_{\alpha,1}+\varphi_{\alpha,2})+(\varphi_{\alpha,1}-\varphi_{\alpha,2})]=h(1+i)
 \end{equation}
 Denoting $q:=i(\varphi_{\alpha,1}+\varphi_{\alpha,2})+(\varphi_{\alpha,1}-\varphi_{\alpha,2})$, we see that we can write
 $\tilde{\cl}=-\partial_x^2+1 - |q|^2$. In addition, $q$ has the representation
 \begin{equation}
 \label{195}
 q=(c_0+c_1 h+O(h^2))\varphi_0+ h \Psi, \ \ \Psi\perp \varphi_0,
 \end{equation}
 where clearly $c_0=i(a_0+b_0)+(a_0-b_0)$ can be expressed in terms of $\alpha_0$. For example, $|c_0|^2=2(a_0^2+b_0^2)=2$. Compute
 \begin{eqnarray*}
 |q|^2 &=& |c_0|^2 \varphi_0^2 +2 h \varphi_0^2 \Re[c_0\bar{c_1}]+h\varphi_0[c_0\bar{\Psi}+\bar{c_0}\Psi]+O(h^2) \\
 &=& 2 \varphi_0^2 + h V_\Psi+O(h^2),
 \end{eqnarray*}
 upon introducing $V_\Psi:=2  \varphi_0^2 \Re[c_0\bar{c_1}]+\varphi_0[c_0\bar{\Psi}+\bar{c_0}\Psi]$.
 It follows that
 $$
 \tilde{\cl}=-\partial_x^2+1 - |q|^2= L_- -h V_\Psi +O(h^2),
 $$
 whence   \eqref{190} becomes
 \begin{equation}
 \label{200}
 (L_--h (V_\Psi+i \alpha_0) +O(h^2))((c_0+c_1 h+O(h^2))\varphi_0+ h \Psi)=h(1+i).
 \end{equation}
 In order to resolve this equation, we need to go in powers of $h$. The terms with power $h^0$ are clearly absent, due to $L_-[\varphi_0]=0$, which is just the profile equation. For the first order in $h$ terms, we have the equation
 \begin{equation}
 \label{220}
 L_-\Psi-(V_\Psi+i \alpha_0)c_0 \varphi_0=1+i.
 \end{equation}
 Taking \eqref{220}, and its complex conjugate,  and in addition the form of $V_\Psi$, $|c_0|^2=2$, we arrive at the system
 \begin{equation}
 \label{210}
 \left(\begin{array}{cc}
 -\partial_x^2+1- 4\varphi_0^2 & -c_0^2 \varphi_0^2 \\
 -\bar{c}_0^2 \varphi_0^2 & -\partial_x^2+1- 4\varphi_0^2
 \end{array}\right) \left(\begin{array}{c}
  \Psi \\ \bar{\Psi}
 \end{array}\right)= \left(\begin{array}{c}
 1+i +i \alpha_0 c_0 \varphi_0 +2 \varphi_0^3 c_0   \Re[c_0\bar{c_1}] \\  1-i -i \alpha_0 \bar{c}_0 \varphi_0 + 2 \varphi_0^3 \bar{c}_0   \Re[c_0\bar{c_1}]
 \end{array}\right)
 \end{equation}
 Diagonalizing the system leads to  the equations
 \begin{eqnarray}
 \label{215}
& &  L_+[\bar{c}_0\Psi+c_0\bar{\Psi}]= c_0+\bar{c}_0+i(\bar{c}_0-c_0)+8 \varphi_0^3  \Re[c_0\bar{c_1}],  \\
 \label{217}
& &  L_-[-\bar{c}_0\Psi+c_0\bar{\Psi}] = c_0-\bar{c}_0-i(c_0+\bar{c}_0)-4 i \alpha_0 \varphi_0.
 \end{eqnarray}
 Note that one  solvability condition for \eqref{217} is exactly $\dpr{c_0-\bar{c}_0-i(c_0+\bar{c}_0)-4 i \alpha_0 \varphi_0}{\varphi_0}=0$. Elementary computations show that this is equivalent to  $b_0 \dpr{1}{\varphi_0}=\alpha_0 \|\varphi_0\|^2$, which is exactly the relation \eqref{185}and \eqref{211}.

 The other relation, is that since $\Psi\perp \varphi_0$, we need to have $\bar{c}_0\Psi+c_0\bar{\Psi}\in \{\varphi_0\}^\perp$.
 This  imposes the relation $L_+^{-1}[c_0+\bar{c}_0+i(\bar{c}_0-c_0)+8 \varphi_0^3  \Re[c_0\bar{c_1}]] \in \{\varphi_0\}^\perp$ or equivalently
 $$
 [c_0+\bar{c}_0+i(\bar{c}_0-c_0)] \dpr{ L_+^{-1}[1]}{\varphi_0}+8  \Re[c_0\bar{c_1}]\dpr{L_+^{-1}[\varphi_0^3]}{\varphi_0}=0.
 $$
 In fact, since $\dpr{ L_+^{-1}[1]}{\varphi_0}=0$ and $\dpr{L_+^{-1}[\varphi_0^3]}{\varphi_0}=-\f{1}{4} \dpr{\varphi_0}{\varphi_0}\neq 0$, it follows that $\Re[c_0\bar{c_1}]=0$.
   It even looks as if we have one degree of  freedom, since $c_1$ is complex valued (and hence two parameters are involved). In the actual non-linear problem however, we need to involve a higher order solvability condition for \eqref{217}, which will finally yield the right number of relations.

Solutions of \eqref{151
- rigorous construction}
 We now setup the full non-linear problem \eqref{151}, with $0<h<<1$, in the equivalent formulation \eqref{190}. More precisely, armed with the results from our informal analysis, we  set the unknown function \\  $q=\varphi_{\alpha,1}-\varphi_{\alpha,2}+i(\varphi_{\alpha,1}+\varphi_{\alpha,2}) \in L^2_{per.}[-T,T]$ in the form
 $$
 q=(c+d h)\varphi_0+ h \Psi, \Psi\perp \varphi_0
 $$
 where
 $$
 c=a_0-b_0+i(a_0+b_0),
 $$
  and $a_0, b_0$ are given by \eqref{180}, \eqref{185} and \eqref{211}), in terms of $\alpha_0$. Note that $|c|^2=2$. Also, in accordance with \eqref{211}, we require $\alpha_0: 0<\alpha_0 < \f{\dpr{1}{\varphi_0}}{\|\varphi_0\|^2}$.

Now that we have set $q$ (and in particular $a_0, b_0$), we are looking for a scalar function $d=d(h)$ and a function $\Psi(h)\in \{\varphi_0\}^\perp$, so that \eqref{190} holds. We compute
$$
|q|^2=2\varphi_0^2 +h V+h^2[|d|^2\varphi_0^2+\varphi_0(d \bar{\Psi}+\bar{d} \Psi) +|\Psi|^2],
$$
 where
 $$
 V= 2  \varphi_0^2 \Re[c\bar{d}]+2 \varphi_0\Re[c \bar{\Psi}]
 $$
  is a real-valued function as
  before. Introduce the {\it real-valued function}
 $$
 G=G(d, \Psi)=|d|^2\varphi_0^2+\varphi_0(d \bar{\Psi}+\bar{d} \Psi) +|\Psi|^2.
 $$
 We thus have a formula for $\tilde{\cl}$ as follows
 $$
 \tilde{\cl}=-\partial_x^2+1- |q|^2= -\partial_x^2+1-2\varphi_0^2 - h V - h^2 G=L_- - h V -h^2 G.
 $$
 Plugging this in \eqref{190}, we obtain the following relation
 \begin{equation}
 \label{300}
 (L_- - h(V+i\alpha_0)-h^2 G)[(c+d h)\varphi_0+h \Psi]=h(1+i).
 \end{equation}
 After some algebraic manipulations,  we obtain
  \begin{equation}
  \label{310}
  L_- \Psi-c(V+i \alpha_0)\varphi_0-(1+i)-h[(V+i\alpha_0)(d \varphi_0 +\Psi)+c \varphi_0 G]=h^2 G(d, \Psi)\Psi.
  \end{equation}
 Similar to the derivation of \eqref{210}, we take \eqref{310} and its complex conjugate to obtain the following {\it non-linear} in $h$ system of equations
  \begin{eqnarray*}
  & & \left(\begin{array}{cc}
  -\partial_x^2+1- 4\varphi_0^2 & -c^2 \varphi_0^2 \\
  -\bar{c}^2 \varphi_0^2 & -\partial_x^2+1- 4\varphi_0^2
  \end{array}\right) \left(\begin{array}{c}
  \Psi \\ \bar{\Psi}
  \end{array}\right) =  \left(\begin{array}{c}
  1+i +i \alpha_0 c \varphi_0 +2 \varphi_0^3 c   \Re[c\bar{d}] \\  1-i -i \alpha_0 \bar{c} \varphi_0 + 2 \varphi_0^3 \bar{c}   \Re[c\bar{d}]
  \end{array}\right)+ \\
  &+& h \left(\begin{array}{c}
  	 (V+i\alpha_0)(d\varphi_0 +\Psi)+c \varphi_0 G \\
  	 (V-i\alpha_0)(\bar{d} \varphi_0 +\bar{\Psi})+\bar{c}\varphi_0 G
  \end{array}\right)+h^2 \left(\begin{array}{c}
   G(d, \Psi)\Psi \\G(d, \Psi)\bar{\Psi}
\end{array}\right)
  \end{eqnarray*}
 Diagonalizing yields the equivalent equations
  \begin{eqnarray}
  \label{315}
    L_+[\bar{c}\Psi+c\bar{\Psi}] &=&  4a_0 +8 \varphi_0^3  \Re[c\bar{d}]+h E_1(h,d,\Psi),     \\
   \label{317}
 L_-[-\bar{c}\Psi+c\bar{\Psi}]  &=&    4i( b_0- \alpha_0 \varphi_0) +
 \\
 \nonumber
 &+& 2 i h[ V\varphi_0\Im[c\bar{d}]+V \Im[c\bar{\Psi}] - \alpha_0 \varphi_0\Re[c \bar{d}]-\alpha_0 \Re[c\bar{\Psi}]]+ h^2 E_2,
  \end{eqnarray}
  where $E_1,E_2$ are smooth functions of the respective arguments.
 This is the system that we need to solve - that is, the goal is to find a neighborhood $(0,h_0)$, so that for every $h\in (0,h_0)$, there is a scalar function $d=d(h)$ and a function $\Psi=\Psi(h)\in \{\varphi_0\}^\perp$, so that the pair satisfies the previous two relations.

 To that end, we shall use the implicit function theorem.  It is clear that it is more convenient to introduce two real  variables\footnote{recall that $c$ is already fixed in terms of $\alpha_0$, so finding $D_1, D_2$ is akin to finding the complex number  $d$} $D_1:=\Re[c\bar{d}], D_2:=\Im[c\bar{d}]$. Clearly, the system requires some solvability conditions. We have already established that with our choice of $c$, we have that $c-\bar{c} -i(c+\bar{c})-4 i \alpha_0 \varphi_0\perp \varphi_0$. So, from \eqref{317},  we need to require
 \begin{eqnarray*}
 	0 &=& \dpr{V\varphi_0\Im(c\bar{d})+V \Im[c\bar{\Psi}]- \alpha_0 \varphi_0\Re[c \bar{d}]-\alpha_0 \Re [c\bar{\Psi}]}{\varphi_0}+O(h)= \\
 	&=&
 	\dpr{D_2 V\varphi_0 - D_1 \alpha_0 \varphi_0 + V \Im[c\bar{\Psi}]}{\varphi_0}+O(h)
 \end{eqnarray*}
 In the last identity, we used that    $\Psi\perp \varphi_0$, whence  by the reality of $\varphi_0$, we have that $\bar{\Psi}\perp \varphi_0$ as well (and thus  any linear combination of $\Psi, \bar{\Psi}$ is perpendicular to $\varphi_0$).  Thus, we end up requiring
 \begin{equation}
 \label{320}
 \dpr{D_2 V\varphi_0 - D_1 \alpha_0 \varphi_0 + V \Im[c\bar{\Psi}]}{\varphi_0}+O(h)=0
 \end{equation}
 Since  $\bar{c}\Psi+c\bar{\Psi}\perp \varphi_0$  ,  we need to have
$$
 0=4 a_0 \dpr{L_+^{-1}[1]}{\varphi_0} +8  D_1 \dpr{L_+^{-1}[\varphi_0^3]}{1}+O(h).
 $$
 Recalling that $\dpr{L_+^{-1}[1]}{\varphi_0}=0$ and   $L_+[\varphi_0]=-4\varphi_0^3$,  whence  $L_+^{-1}[\varphi_0^3]=-\f{1}{4}\varphi_0$ and the previous relation reads
 \begin{equation}
 \label{330}
-2D_1 \dpr{\varphi_0}{1} +O(h)=0.
 \end{equation}
 The analysis so far allows us to solve the system\eqref{315}, \eqref{317}, for $h=0$.   Namely,  from \eqref{330}, we infer  that
 \begin{equation}
 \label{340}
 D_1^0=0
 \end{equation}
 The next step is to find $\Psi^0$, from \eqref{315}and \eqref{317}, at $h=0$. Inverting   $L_+$ in \eqref{315} and $L_-$ in \eqref{317} and taking the difference,  and taking into account that $\Re[c\bar{d}]=D_1^0+O(h)=O(h)$, we obtain\footnote{Recall that  $b_0-\alpha_0 \varphi_0\perp \varphi_0$, so taking $L_-^{-1}$  is justified. Similarly, with the definition of $D_1^0$ in \eqref{340}, taking $L_+^{-1}$ is justified as well.}
  \begin{equation}
 \label{350}
   \Psi^0 =  \f{4 a_0  L_+^{-1}[1]- 4 i L_-^{-1}[ b_0 - \alpha_0 \varphi_0]}{2\bar{c}}= c a_0 L_+^{-1}[1] - i c L_-^{-1}[ b_0 - \alpha_0\varphi_0].
 \end{equation}
 Note that $\Psi^0\perp \varphi_0$ (as it should be), since $L_+^{-1}[1]\perp \varphi_0$, and
 $Image[ L_-^{-1}]\perp \varphi_0$.


  Finally, we use \eqref{320} to determine $D_2^0$. We obtain the formula
 \begin{equation}
 \label{c:14}
 D_2^0\dpr{V^0 \varphi_0}{\varphi_0}=-\dpr{\Im[c\bar{\Psi}_0]}{V^0 \varphi_0}.
 \end{equation}
  We clearly need to compute $\Re[c\bar{\Psi}_0], \Im[c\bar{\Psi}_0]$. We have from \eqref{350},
  \begin{eqnarray*}
\Re[c\bar{\Psi}_0] &=&    2 a_0  L_+^{-1}[1],      \\
\Im[c\bar{\Psi}_0]&=&  2 L_-^{-1}[b_0-\alpha_0 \varphi_0].
  \end{eqnarray*}
  According to its definition
  $$
  V^0=V(0, \Psi_0)=2  \varphi_0^2 D_1^0+\varphi_0[c \bar{\Psi^0}+\bar{c}\Psi^0]=2\varphi_0\Re[c\bar{\Psi}_0]=
  2 a_0  \varphi_0 L_+^{-1}[1].
  $$
  Consequently, since $L_+^{-1}[\varphi_0^3]=-\f{1}{4} \varphi_0$,
   \begin{equation}
   \label{c:27}
   	 \dpr{V^0 \varphi_0}{\varphi_0} = 4 a_0  \dpr{\varphi_0^3}{L_+^{-1}[1]}= - a_0  \dpr{1}{\varphi_0}.
   \end{equation}
   Finally,
     \begin{eqnarray*}
   \dpr{\Im[c\bar{\Psi}_0]}{V^0 \varphi_0} = 8 a_0 \dpr{\varphi_0^2 L_+^{-1}[1]}{L_-^{-1}[b_0-\alpha_0 \varphi_0]}.
      \end{eqnarray*}
      From \eqref{c:14}, we deduce
      \begin{equation}
      \label{c:17}
       D_2^0=  8 \f{\dpr{\varphi_0^2 L_+^{-1}[1]}{L_-^{-1}[b_0-\alpha_0 \varphi_0]}}{\dpr{1}{\varphi_0}}
      \end{equation}



 To recapitulate, we have determined, in  \eqref{350}, together with $D_1^0, D_2^0$ as determined above,
 the unique solutions of \eqref{315} and \eqref{317}, when $h=0$.
 We now setup the implicit function argument, which will work in a neighborhood of the solution $h=0$, $\Psi^0$, given by \eqref{350}, and $ D_1^0, D_2^0$.






 First, we set the solvability condition arising in \eqref{317}, namely the scalar function\footnote{Here we use again that $\dpr{ \Im[c\bar{\Psi}]}{\varphi_0}=0$}
 \begin{eqnarray*}
& & Q_1(h; \Psi, D_1, D_2) = 2i\dpr{D_2  V(D_1, \Psi)\varphi_0 +V \Im[c\bar{\Psi}] - \alpha_0 \varphi_0 D_1 -\alpha_0 \Im[c\bar{\Psi}]}{\varphi_0}+ \\
&+& h \dpr{E_2(h,\Psi, D_1, D_2)}{\varphi_0}  = 2i\dpr{D_2  V(D_1, \Psi)\varphi_0 + V(D_1, \Psi) \Im[c\bar{\Psi}]  - \alpha_0 \varphi_0D_1 }{\varphi_0}+\\
&+& h \dpr{E_2(h,\Psi, D_1, D_2)}{\varphi_0},
