\begin{proof}
	Let $\varphi_{\alpha}=\varphi_{\alpha, 1}+i\varphi_{\alpha, 2}$ be  a solution of \eqref{110}. Then, we have
	\begin{equation}
	\label{120}
	\left| \begin{array}{ll} \varphi_{\alpha,1}^{''}-\varphi_{\alpha,1}+2(\varphi_{\alpha,1}^2+\varphi_{\alpha, 2}^2)\varphi_{\alpha, 1}-\alpha\varphi_{\alpha, 2}=0 \\
	\\
	\varphi_{\alpha,2}^{''}-\varphi_{\alpha,2}+2(\varphi_{\alpha,1}^2+\varphi_{\alpha, 2}^2)\varphi_{\alpha, 2}+\alpha\varphi_{\alpha, 1}=0.
	\end{array} \right.
	\end{equation}
	Denoting the second order self-adjoint differential operator $L:=-\partial_x^2+1 - 2(\varphi_{\alpha,1}^2+\varphi_{\alpha, 2}^2)$, we see that \eqref{120} is a relationship in the form
	$$
	\left| \begin{array}{l}
	L[\varphi_{\alpha,1}]=-\alpha \varphi_{\alpha,2} \\
	L[\varphi_{\alpha,2}]=\alpha \varphi_{\alpha,1}.
	\end{array}
	\right.
	$$
	Thus, applying $L$ to to first equation, we obtain $L^2[\varphi_{\alpha,1}]=-\alpha^2 \varphi_{\alpha,1}$. By taking a dot product with $\varphi_{\alpha,1}$, we obtain
	$$
	0\leq \|L \varphi_{\alpha,1}\|^2=\dpr{L^2[\varphi_{\alpha,1}]}{\varphi_{\alpha,1}}=-\alpha^2\|\varphi_{\alpha,1}\|^2<0,
	$$
	which  is a contradiction.
\end{proof}

\begin{proof}
  Take a dot product with $\varphi=\varphi_1+i \varphi_2$ in \eqref{1.15}. Then, since its left-hand side is real, taking imaginary parts results in
  $$
  \alpha \|\varphi\|^2 = h \int_{-T}^T  \varphi_2(x) dx\leq h \sqrt{2 T} \|\varphi\|
  $$
  This implies that $\alpha=O(h)$.
  \end{proof}

  Now that we know that $\alpha=O(h)$, we take the ansatz $\alpha=\alpha_0 h$.  Our next result describes the existence of waves for $0<h<<1$, $\alpha=\alpha_0  h$,  which only holds for  specific range of $\alpha_0$.  In order to state the result, we introduce the operators ${\mathcal L}_\pm$,
  \begin{eqnarray*}
  	{\mathcal L}_{+,h} &=& -\partial_x^2+1-6\varphi_h^2\\
  	{\mathcal L}_{-,h} &=& -\partial_x^2+1-2\varphi_h^2
  \end{eqnarray*}
  which will be important for our arguments in the sequel. Also, $L_\pm:={\mathcal L}_{\pm,0}$.

{\bf Remarks:}
  \begin{enumerate}
  	\item Note that by Proposition \ref{prop:h0} below, $Ker[L_-]=span[\varphi_0], Ker[L_+]=span[\varphi_0']$. Therefore,  the expression  $L_-^{-1}[b_0-\alpha_0\varphi_0]$ is well-defined, since by the definition of $b_0$, we have that $b_0-\alpha_0\varphi_0\perp Ker[L_-]$. Similarly, $1\perp Ker[L_+]$, whence $L_+^{-1}[1]$ is well-defined.
  	\item The theorem applies under the more general ansatz $\alpha=\alpha_0 h+O(h^2)$. In fact, since its statement is a first order in $h$, the proof in this more general case, goes without any changes or modifications.
  \end{enumerate}

  We also have the following theorem regarding the stability of these solutions.

